void emitu(uint32_t v);
uint32_t input_len(void);
uint8_t input_byte(uint32_t i);

#define REG (*(volatile uint32_t *)0x10370000u)

int main(void)
{
    static const uint32_t shift[4] = {0u, 4u, 8u, 31u};
    static const uint32_t maxv[4]  = {1u, 3u, 4095u, 1u};

    REG = 0u;
    uint32_t n = input_len();
    for (uint32_t i = 0; i + 1 < n; i += 2) {
        uint32_t f = input_byte(i);
        uint32_t v = input_byte(i + 1);
        if (f > 3u) {
            emit(-1);
            continue;
        }
        uint32_t num = (f == 2u) ? v * 16u : v;
        if (num > maxv[f]) {
            emit(-1);
            continue;
        }
        uint32_t mask = maxv[f] << shift[f];
        uint32_t r = REG;
        r = (r & ~mask) | ((num << shift[f]) & mask);
        REG = r;
        emitu(REG);
    }
    return 0;
}

