{
    REG = 0;
    uint32_t n = input_len();
    for (uint32_t i = 0; i + 1 < n; i += 2) {
        uint32_t f = input_byte(i);
        uint32_t v = input_byte(i + 1);
        uint32_t shift, maxv;
        switch (f) {
        case 0: shift = 0; maxv = 1; break;
        case 1: shift = 4; maxv = 3; break;
        case 2: shift = 8; maxv = 0xFFF; v = v * 16u; break;
        case 3: shift = 31; maxv = 1; break;
        default: emit(-1); continue;
        }
        if (v > maxv) { emit(-1); continue; }
        uint32_t mask = maxv << shift;
        uint32_t r = REG;
        r = (r & ~mask) | ((v << shift) & mask);
        REG = r;
        emitu(REG);
    }
    return 0;
}

